#!/bin/sh
#
# Regenerate the GD32 CRC32 stub the Rust driver loads into the target.
#
#   ./gd32_mkstub.sh
#
# Builds `gd32_crc32.c` into Thumb machine code and rewrites `../../flashstub_crc32.rs`
# (crate `src/flashstub_crc32.rs`), the byte image `rs_stm32f1::crc32` copies into the
# target's SRAM. This is a manual, developer-only step: it needs an ARM C toolchain,
# while the probe build only compiles the generated Rust file. The generated file is
# therefore checked in, and this script is here to reproduce it.
#
# Override the toolchain with `ARM_GCC=/path/to/arm-none-eabi-gcc ./gd32_mkstub.sh`.
# (Only GCC can build this stub: the function is `naked` and still contains C
# statements, which current clang rejects outright.)
set -eu

ARM_GCC=${ARM_GCC:-/arm/15.2.1/bin/arm-none-eabi-gcc}
PREFIX=$(dirname "${ARM_GCC}")/arm-none-eabi-
OBJCOPY=${OBJCOPY:-${PREFIX}objcopy}
OBJDUMP=${OBJDUMP:-${PREFIX}objdump}
# The stub has to run on the oldest cores of the family (Cortex-M3/M23), so keep the
# baseline CPU; the CRC unit sits at a fixed address, so no headers are needed.
CPU=${CPU:--mcpu=cortex-m3}

SRC=gd32_crc32
OUT=../flashstub_crc32.rs
# The C driver keeps its own copy of the image (`stm32f1.c` includes it); that one was
# built with an older toolchain, so compare the two and say so when they differ.
C_STUB=../../../../../../flashstub/gd32_crc32.stub

build_stub() {
    rm -f "${SRC}.o" "${SRC}.bin" "${SRC}.asm"
    "${ARM_GCC}" "${SRC}.c" -g -O2 -c ${CPU} -o "${SRC}.o" -nostdlib -I ../../../include
    "${OBJCOPY}" -Obinary "${SRC}.o" "${SRC}.bin"
    "${OBJDUMP}" -S "${SRC}.o" >"${SRC}.asm"
}

# The bytes live in one checked-in Rust file so the driver has no hand-copied array.
emit_rust() {
    length=$(wc -c <"${SRC}.bin" | tr -d ' ')
    {
        printf '%s\n' \
            '//! Machine code of the GD32 CRC32 flash stub.' \
            '//!' \
            '//! GENERATED by `src/flashstub/gd32_mkstub.sh` from `src/flashstub/gd32_crc32.c`:' \
            '//! run that script after touching the stub source and commit the result. The' \
            '//! probe build never runs it (an ARM C toolchain would be needed for that).' \
            '' \
            '/// Stub length in bytes (C `GD32_CRC32_BIN_LEN`).' \
            "pub const GD32_CRC32_BIN_LEN: usize = ${length};" \
            '' \
            '/// The stub itself: `bkpt 1` with the CRC in `r1` once it is done.' \
            'pub static GD32_CRC32_BIN: [u8; GD32_CRC32_BIN_LEN] = ['
        # `xxd -i` prints a C array: turn it into a Rust one line by line -- C
        # declaration and length variable dropped, closing brace translated, bytes
        # re-indented to rustfmt's four spaces with a trailing comma on every line.
        xxd -i -c 16 "${SRC}.bin" | awk '
            NR == 1 { next }
            /_len =/ { next }
            /^};$/ { print "];"; next }
            /^  / { line = substr($0, 3); print "    " line ((line ~ /,$/) ? "" : ",") }
        '
    } >"${OUT}"
}

build_stub
emit_rust
rm -f "${SRC}.o" "${SRC}.bin"
printf '%s\n' "wrote ${OUT} - ${SRC}.asm kept for inspection"

if [ -f "${C_STUB}" ]; then
    c_length=$(sed -n 's/^#define GD32_CRC32_BIN_LEN \([0-9][0-9]*\)$/\1/p' "${C_STUB}")
    length=$(sed -n 's/^pub const GD32_CRC32_BIN_LEN: usize = \([0-9][0-9]*\);$/\1/p' "${OUT}")
    if [ "${c_length}" != "${length}" ]; then
        printf '%s\n' "note: ${C_STUB} is a different image - same algorithm, older codegen"
    fi
fi
